import{_ as i,H as e,f as a,i as p}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"28 | 投资是一场无限游戏：活得久，才是最高的阿尔法","description":"","frontmatter":{},"headers":[{"level":2,"title":"赢家的诅咒：为什么冠军常死于归零？","slug":"赢家的诅咒-为什么冠军常死于归零","link":"#赢家的诅咒-为什么冠军常死于归零","children":[]},{"level":2,"title":"复利的谎言与真相：时间是你的朋友","slug":"复利的谎言与真相-时间是你的朋友","link":"#复利的谎言与真相-时间是你的朋友","children":[]},{"level":2,"title":"从猎人进化为农夫","slug":"从猎人进化为农夫","link":"#从猎人进化为农夫","children":[]},{"level":2,"title":"所谓的财务自由，其实是选择权的自由","slug":"所谓的财务自由-其实是选择权的自由","link":"#所谓的财务自由-其实是选择权的自由","children":[]},{"level":2,"title":"像 AI 一样思考：去情绪化的人生","slug":"像-ai-一样思考-去情绪化的人生","link":"#像-ai-一样思考-去情绪化的人生","children":[]},{"level":2,"title":"AI 量化策略建议","slug":"ai-量化策略建议","link":"#ai-量化策略建议","children":[]},{"level":2,"title":"本讲金句弹幕","slug":"本讲金句弹幕","link":"#本讲金句弹幕","children":[]},{"level":2,"title":"课后思考题","slug":"课后思考题","link":"#课后思考题","children":[]},{"level":2,"title":"下节预告","slug":"下节预告","link":"#下节预告","children":[]}],"relativePath":"人人都用得上的AI量化思维课/28｜投资是一场无限游戏：活得久，才是最高的阿尔法.md","filePath":"人人都用得上的AI量化思维课/28｜投资是一场无限游戏：活得久，才是最高的阿尔法.md","lastUpdated":1795541548000}'),t={name:"人人都用得上的AI量化思维课/28｜投资是一场无限游戏：活得久，才是最高的阿尔法.md"};function r(n,l,o,h,s,d){return e(),a("div",null,[...l[0]||(l[0]=[p('<h1 id="_28-投资是一场无限游戏-活得久-才是最高的阿尔法" tabindex="-1">28 | 投资是一场无限游戏：活得久，才是最高的阿尔法 <a class="header-anchor" href="#_28-投资是一场无限游戏-活得久-才是最高的阿尔法" aria-label="Permalink to &quot;28 | 投资是一场无限游戏：活得久，才是最高的阿尔法&quot;">​</a></h1><p>你好，我是陈旸。</p><p>1986 年，哲学家詹姆斯·卡斯写了一本神书，叫《有限与无限的游戏》。书中把世界上的活动分为两类，有限游戏和无限游戏。</p><p>有限游戏是为了赢。它有明确的开始和结束，有固定的规则，有赢家和输家。比如，一场足球赛、一次高考、一局德州扑克、一轮牛市的博弈。</p><p>无限游戏是为了继续玩下去。它没有终点，规则可以改变，没有所谓的赢，只有存续或出局。比如，生物进化、企业经营、以及……个人财富管理。</p><p>金融市场的残酷之处在于：它表面上看起来像一个充满了 K 线波动的有限游戏（大家都在比谁今天赚得多），但本质上，它是一个残酷筛选的无限游戏。</p><p>如果你用有限游戏的心态（我要赢，我要翻倍，我要击败庄家）去玩无限游戏，结局注定是悲剧。</p><h2 id="赢家的诅咒-为什么冠军常死于归零" tabindex="-1">赢家的诅咒：为什么冠军常死于归零？ <a class="header-anchor" href="#赢家的诅咒-为什么冠军常死于归零" aria-label="Permalink to &quot;赢家的诅咒：为什么冠军常死于归零？&quot;">​</a></h2><p>在量化交易中，你可能会看到一种现象：短期业绩榜单的第一名，往往也是死得最快的那一个。</p><p>场景示例：</p><ul><li><p>选手 A（赌徒心态）：全仓梭哈妖股，加了 5 倍杠杆。运气好，一个月翻了 5 倍。他是这个月的冠军，享受着众人的膜拜。</p></li><li><p>选手 B（量化心态）：多策略对冲，控制回撤，从不梭哈。一个月赚了 3%。没人注意他，觉得他太怂。</p></li></ul><p>在有限游戏的视角（比如只看这一个月），A 是赢家，B 是输家。但在无限游戏的视角（比如拉长到 10 年），会发生什么？A 因为习惯了梭哈和暴利，他的风险阈值被拉高了。他觉得一个月赚 20% 都算亏。</p><p>根据概率论（我们之前学过的凯利公式），只要他一直留在牌桌上，总会遇到一次黑天鹅。因为他满仓加杠杆，这一次黑天鹅就能让他从 1000 万变成 0（甚至负债）。只要归零一次，游戏就结束了。你在前面赢了 99 次都没用，因为你无法参加第 101 局了。</p><p>而 B，虽然每个月只赚 3%，但如果不亏损，10 年后是几十倍的收益。更重要的是，他在第101 局、第 1000 局，依然在桌上。</p><p>量化思维的第一定律：投资不是为了战胜市场，而是为了不下牌桌。在无限游戏中，生存本身就是胜利。</p><h2 id="复利的谎言与真相-时间是你的朋友" tabindex="-1">复利的谎言与真相：时间是你的朋友 <a class="header-anchor" href="#复利的谎言与真相-时间是你的朋友" aria-label="Permalink to &quot;复利的谎言与真相：时间是你的朋友&quot;">​</a></h2><p>提到无限游戏，就绕不开复利。爱因斯坦说它是世界第八大奇迹。在理想情况下：如果你每天赚 1%，一年后你的本金将变成 37 倍！这是数学上的真理，却是现实中的谎言。因为在现实中，没有人能做到每天稳赚 1% 且不回撤。现实中的复利，最大的敌人是波动率。</p><p>让我们看两个公式：</p><ol><li><p>算术平均收益：(+50% - 50%) / 2 = 0%，即不亏不赚。</p></li><li><p>几何平均收益：(1+0.5) * (1-0.5) = 0.75，即你亏了 25%。</p></li></ol><p>这就是我们在风控课里讲的波动率税。在无限游戏中，稳健比暴利更有爆发力。</p><p>巴菲特的秘密：巴菲特 99% 的财富是在他 50 岁以后赚到的。他的年化收益率是多少？只有20% 左右。这个数字在 A 股很多散户眼里简直弱爆了（抓个涨停板就 10% 了）。但巴菲特的可怕之处在于：他把这个 20% 维持了 50 多年。他没有在某一年赚 200%，也没有在某一年亏光。他把自己变成了一个低波动、正期望的函数，然后把剩下的交给了时间。</p><p>AI 量化的使命：我们开发 AI，做多策略，做风控，不是为了把年化收益从 20% 提到 200%。而是为了把最大回撤从 30% 降低到 10%。因为只有把波动降下来，你才能拿得住；只有拿得住，复利才能在最后几年通过指数级爆炸，送你上青云。</p><h2 id="从猎人进化为农夫" tabindex="-1">从猎人进化为农夫 <a class="header-anchor" href="#从猎人进化为农夫" aria-label="Permalink to &quot;从猎人进化为农夫&quot;">​</a></h2><p>在无限游戏里，我们需要通过改变心态，来改变行为。</p><ol><li>猎人思维（有限游戏）</li></ol><ul><li><p>关注点：哪里有猎物？（哪里有大牛股？哪个板块最热？）</p></li><li><p>动作：瞄准、射击、追逐。</p></li><li><p>结果：有时候吃得很饱，有时候饿死。一旦受伤（亏损），就无法打猎。</p></li><li><p>代表策略：打板、梭哈、听消息。</p></li></ul><ol start="2"><li>农夫思维（无限游戏）</li></ol><ul><li><p>关注点：土壤怎么样？天气怎么样？（宏观环境、资产配置、风控体系）。</p></li><li><p>动作：播种、施肥、除草、等待。</p></li><li><p>结果：收成有大年小年，但不会绝收。随着果树长大，收益越来越稳。</p></li><li><p>代表策略：多因子选股、网格交易、资产配置（股票 + 债券 + 商品）。</p></li></ul><p>AI 是什么？</p><p>AI 不是你打猎的枪（虽然它也可以是），AI 更应该是你的自动化农业机械。它帮你监控每一寸土壤（数据），帮你自动浇水（定投），帮你自动除虫（风控）。它让你从看天吃饭变成了科学种植。</p><h2 id="所谓的财务自由-其实是选择权的自由" tabindex="-1">所谓的财务自由，其实是选择权的自由 <a class="header-anchor" href="#所谓的财务自由-其实是选择权的自由" aria-label="Permalink to &quot;所谓的财务自由，其实是选择权的自由&quot;">​</a></h2><p>在这个无限游戏中，我们要玩到什么时候是个头？很多人做量化的初衷是财务自由。但大多数人对财务自由的定义是错的。他们认为是一个具体的数字：赚够 1000 万我就收手。这是一个陷阱。如果你是为了赚 1000 万而在这个市场里搏杀，当你赚到 500 万时，你会想赚 2000万；当你亏回 200 万时，你会想回本。你会永远在贪婪和恐惧中轮回。</p><p>在无限游戏的视角下，财富不是终点，而是燃料。</p><ul><li><p>第一阶段（燃料积累）：利用工作收入、量化策略，积累本金。</p></li><li><p>第二阶段（燃料循环）：建立一套睡后收入系统（比如低风险的量化网格、分红策略）。当这套系统的产出 &gt; 你的生活成本时，你就自由了。</p></li></ul><p>自由不是不工作，而是可以说不。</p><ul><li><p>你可以对不喜欢的上司说不。</p></li><li><p>你可以对高风险但看不懂的行情说不。</p></li><li><p>你可以对必须时刻盯盘、消耗生命的短线策略说不。</p></li></ul><p>量化交易的终极意义不是为了让你变成世界首富，而是为了把你从枯燥的盯盘、焦虑的决策中解放出来。把赚钱这件事交给没有感情的代码，把时间留给你的家人、健康和真正的爱好。这才是真正的赢。</p><h2 id="像-ai-一样思考-去情绪化的人生" tabindex="-1">像 AI 一样思考：去情绪化的人生 <a class="header-anchor" href="#像-ai-一样思考-去情绪化的人生" aria-label="Permalink to &quot;像 AI 一样思考：去情绪化的人生&quot;">​</a></h2><p>AI 之所以是无限游戏的完美玩家，因为它具备两个人类最稀缺的品质：</p><ol><li><p>无我：AI 亏钱了，不会觉得自己无能，不会为了面子去死扛单子。它只会修正概率。人类往往不是输给了市场，而是输给了自尊心。</p></li><li><p>耐心：AI 可以等待一个信号，等待一年，如果不触发，它就一年不动。人类空仓三天就受不了了，觉得踏空比亏损更难受。</p></li></ol><p>修行建议：虽然我们是肉体凡胎，但我们可以通过修炼来接近 AI 的境界。</p><ul><li><p>把账户看作一个数字游戏：别把钱当成孩子的奶粉钱或明年的房贷。用闲钱做交易，你才能拥有 AI 般的冷静。</p></li><li><p>承认无知：像索罗斯一样，时刻准备承认我看错了。砍仓不是羞耻，是风控。</p></li><li><p>享受无聊：好的投资通常是无聊的。如果你在交易中感到了巨大的刺激和快感，那你大概率是在赌博。</p></li></ul><h2 id="ai-量化策略建议" tabindex="-1">AI 量化策略建议 <a class="header-anchor" href="#ai-量化策略建议" aria-label="Permalink to &quot;AI 量化策略建议&quot;">​</a></h2><p>请记住以下三个锦囊，作为你行走江湖的护身符：</p><ol><li>盈亏同源，接受波动</li></ol><p>不要试图寻找只赚不亏的圣杯。利润是对你承担风险的补偿。如果你接受不了回撤，你就不仅享受不到复利，还会死在黎明前。拥抱波动，利用波动（网格 / 期权），而不是恐惧波动。</p><ol start="2"><li><p>弱水三千，只取一瓢市场上的钱是赚不完的。AI 热点来了，你没赶上；商业航天起来了，你没赶上。没关系。无限游戏的关键是：只要你在你的策略射程范围内（能力圈），赚到了你该赚的那部分，就足够了。因为嫉妒别人的收益而打乱自己的节奏，是大忌。</p></li><li><p>长期主义是最高级的算法</p></li></ol><p>在短视的世界里，长期主义者是无敌的。当所有人都想做高频、做 T+0、做一夜暴富时，你把目光放长到 5 年、10 年。你会发现，竞争对手少了很多，路越走越宽。慢慢变富，其实是变富最快的路径。</p><h2 id="本讲金句弹幕" tabindex="-1">本讲金句弹幕 <a class="header-anchor" href="#本讲金句弹幕" aria-label="Permalink to &quot;本讲金句弹幕&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/28/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/28/1.png" alt=""></a></p><h2 id="课后思考题" tabindex="-1">课后思考题 <a class="header-anchor" href="#课后思考题" aria-label="Permalink to &quot;课后思考题&quot;">​</a></h2><p>请拿出纸笔，或者打开 Excel。不要计算下个月能赚多少。请计算一下：如果我现在的本金，每年能稳定获得 15% 的收益（这是一个合理的量化目标），20 年后会是多少？看着那个数字。然后问自己：为了这个数字，我是否愿意放弃那些一周翻倍的诱惑？我是否愿意忍受中间必然出现的 30% 回撤？如果你愿意，那么恭喜你。你已经拿到了无限游戏的入场券。</p><h2 id="下节预告" tabindex="-1">下节预告 <a class="header-anchor" href="#下节预告" aria-label="Permalink to &quot;下节预告&quot;">​</a></h2><p>心态建设完毕。现在，你已经准备好迈出最后一步了。但是，路要一步步走，饭要一口口吃。从零开始学 Python？还是直接用 QMT？先实盘还是先回测？你需要一张清晰的进阶地图。</p>',54)])])}const _=i(t,[["render",r]]);export{c as __pageData,_ as default};
